window.setLifetime=(id,enabled)=>{if(role!=='adm')return;const p=data.personalAccounts.find(p=>p.id===id);if(!p)return;p.lifetime=Boolean(enabled);if(enabled)data.licenseRequests.filter(r=>r.personalId===id&&r.status==="pendente").forEach(r=>{r.status="dispensada (vitalício)";r.resolved=new Date().toISOString()});p.lifetimeUpdated=new Date().toISOString();save();render();toast(enabled?'Uso vitalício ativado com licenças ilimitadas.':'Uso vitalício desativado. O limite anterior foi mantido.')};
const limitedHasLicense=hasLicense;hasLicense=()=>personalAccount().lifetime||limitedHasLicense();
const limitedRequest=window.requestLicenses;window.requestLicenses=()=>{if(role==='personal'&&personalAccount().lifetime){toast('Seu acesso vitalício já possui licenças ilimitadas.');return}limitedRequest()};
const limitedPanel=licensePanel;licensePanel=function(){const p=personalAccount();if(!p.lifetime)return limitedPanel();return `<section class="card license-panel"><span class="tag">∞ USO VITALÍCIO</span><h2>Licenças ilimitadas.</h2><p>${licenseUsage()} alunos cadastrados. Você pode criar novos acessos sem solicitar lotes ao ADM.</p><p class="note">Uso sem vencimento, concedido pelo administrador. Não há limite de cadastro de alunos para este personal.</p></section>`};
const priorAdminScreen=adminScreen;adminScreen=function(){let html=priorAdminScreen();for(const p of data.personalAccounts){const original=`<span class="tag">${licenseUsage(p.id)} / ${p.limit} LICENÇAS</span></section>`;const replacement=`<span class="tag">${p.lifetime?'∞ LICENÇAS ILIMITADAS':`${licenseUsage(p.id)} / ${p.limit} LICENÇAS`}</span><div class="lifetime-setting"><span class="tag">${p.lifetime?'USO VITALÍCIO · SEM VENCIMENTO':'ACESSO COM LIMITE'}</span><button class="${p.lifetime?'primary':''}" aria-pressed="${Boolean(p.lifetime)}" onclick="setLifetime('${p.id}',${!p.lifetime})">${p.lifetime?'Desativar uso vitalício':'Ativar uso vitalício'}</button><p class="note">${p.lifetime?`Ao desativar, volta ao limite anterior de ${p.limit} licenças. Alunos existentes permanecem cadastrados.`:'Ative para conceder uso vitalício com cadastro ilimitado de alunos.'}</p></div></section>`;html=html.replace(original,replacement)}return html};

